/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Pow, rational, rebuild, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("sympy/strategies/tests/test_traverse.py", () => {
  it("test_expr_fns:84", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(rebuild(new Add([new Add([new Add([x, rational(1)]), new Add([new Pow(new Add([y, rational(1)]), new Add([rational(3), rational(1)])), rational(1)])]), rational(1)])))).toBe('x + (y + 1)**4 + 3');
  });
});
